#!/usr/bin/env bash
# Reproduce the real-validation numbers of 's3' (model-v2x-track/routed-g3) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g3/test/reproduce_s3_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-v2x-track/routed-g3 --tag s3 --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-v2x-track/routed-g3/validation/output/repro_s3
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-s4-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/centerpoint-s4-g1v3 --ckpt model-v2x-track/centerpoint-s4-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/centerpoint-s4-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-s4-g1v3_tta_val.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-s4-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/centerpoint-s4-g1v3 --ckpt model-v2x-track/centerpoint-s4-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/centerpoint-s4-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-s4-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/centerpoint-g1v3 --ckpt model-v2x-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-g1v3_tta_val.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/centerpoint-g1v3 --ckpt model-v2x-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/centerpoint-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v2_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v2_tta_val.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v2_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v2_tta_valB.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v3_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v3_tta_val.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v3_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-g1v3_tta_valB.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-ut_tta_val.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split val --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-ut_tta_val.json
[ -s model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-ut_tta_valB.json ] || python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames pcdet/realval-v1 --split valB --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out model-v2x-track/routed-g3/validation/output/repro_s3/pointpillars-ut_tta_valB.json
python common/tools/reproduce_validation.py model-v2x-track/routed-g3 --tag s3 --score
